        map<int, int> count;  // ordered by card value
        for (int card : hand) {
            count[card]++;
        }

        for (auto& [first, freq] : count) {
            if (freq == 0) {
                continue;
            }

            int frequency = freq;

            for (int value = first; value < first + groupSize; value++) {
                if (count[value] < frequency) {
                    return false;
                }

                count[value] -= frequency;
